#include "modules/cavebot/CavebotEngine.hpp"
namespace crome { void CavebotEngine::tick(const GameState& s,CromeApi& api,ActionScheduler& q){if(!cfg_.enabled||cfg_.waypoints.empty()||!s.player.valid)return; if(index_>=cfg_.waypoints.size()){if(cfg_.loop)index_=0;else return;} auto wp=cfg_.waypoints[index_]; if(wp.type==WaypointType::Walk){ if(s.player.position==wp.position){++index_;return;} q.submit({40,"cavebot",[&api,wp]{api.actions().walkTo(wp.position);}}); return;} if(wp.type==WaypointType::Say){q.submit({40,"cavebot-say",[&api,wp]{api.actions().say(wp.text);}});++index_;return;} if(wp.type==WaypointType::Use){q.submit({40,"cavebot-use",[&api,wp]{api.actions().use(wp.itemId);}});++index_;return;} if(wp.type==WaypointType::UseWith||wp.type==WaypointType::Rope||wp.type==WaypointType::Shovel||wp.type==WaypointType::Ladder||wp.type==WaypointType::Hole){q.submit({40,"cavebot-tool",[&api,wp]{api.actions().useWithGround(wp.itemId,wp.position);}});++index_;return;} ++index_; } }
